const text = String($input.first().json.body?.text ?? '').slice(0, 4000);
const rules = [
  ['Estornos', /estorno|reembolso|devolu[cç][aã]o/i],
  ['Pagamentos', /pagamento|cobran[cç]a|cart[aã]o|\bpix\b/i],
  ['Acesso', /acesso|conta|login|senha|entrar/i],
  ['Entrega', /entrega|entregador|endere[cç]o|pedido/i],
];
const hit = rules.find(([, pattern]) => pattern.test(text));
const high = /urgente|duplicad[ao]|invas[aã]o|bloquead[ao]|atrasad[ao].*(horas|dias)|indevid[ao]/i.test(text);
return [{ json: { ticket: text, team: hit?.[0] ?? 'Revisão manual', severity: hit ? (high ? 'Alta' : 'Média') : 'Indefinida', approvedByHuman: false, note: 'Sugestão somente; aprovação humana deve ocorrer fora deste workflow.' } }];
